text:
.hub-footer {
  grid-area: footer;

  & .center-column {
    justify-content: center;
  }

  & hr {
    border: none;
    block-size: 1px;
    margin-block-start: var(--hub-footer-margin-block);
    background: linear-gradient(to right, transparent, var(--color-surface-border), transparent);
    color: transparent;
  }

  & .footer-button {
    font-size: 1.1rem;
    min-inline-size: 128px;
    padding: 10px 25px;
    text-align: center;
  }

  .busy & {
    z-index: 3;
  }
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 3px 9px;
  justify-content: center;
  align-items: center;
  margin-block: var(--hub-footer-margin-block);

  & li {
    display: flex;
    align-items: center;
    gap: 9px;

    &:not([hidden]) ~ li:not([hidden])::before {
      content: "";
      inline-size: 2px;
      block-size: 2px;
      border-radius: 2px;
      background-color: var(--color-text-muted);
    }
  }

  & li > a {
    font-size: 1.1rem;
    text-decoration: none;
    letter-spacing: 0.2px;
    font-weight: 300;
    color: var(--link-color);

    &:hover {
      text-decoration: underline;
    }
  }
